public static int countDoubles(int[] numbers) {
    int count = 0;
    Map<Integer, Integer> numMap = new HashMap<>();

    for (int num : numbers) {
        numMap.put(num, numMap.getOrDefault(num, 0) + 1);
    }

    for (int num : numbers) {
        int doubleNum = 2 * num;
        if (numMap.containsKey(doubleNum) && numMap.get(doubleNum) > 0) {
            count++;
            numMap.put(doubleNum, numMap.get(doubleNum) - 1);
        }
    }

    return count;
}

