    }
}

public static String appx(String word1, String word2) {
    int commonCount = 0;
    int lengthSum = word1.length() + word2.length();

    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonCount++;
                break; // Only count each letter once per word
            }
        }
    }

    int gcd = greatestCommonDivisor(commonCount, lengthSum);
    return "appx(" + word1 + ", " + word2 + ") = " + (commonCount / gcd) + "/" + (lengthSum / gcd);
}

