public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    Set<Double> seenSums = new HashSet<>();
    for (int i = 1; i <= n / 2; i++) {
        seenSums.clear();
        int target = sum * i / n;
        boolean found = false;
        for (int j = 0; j < 1 << i; j++) {
            int count = 0;
            int total = 0;
            for (int k = 0; k < i; k++) {
                if ((j & (1 << k)) != 0) {
                    count++;
                    total += nums[k];
                }
            }
            if (count > 0 && total == target) {
                return true;
            }
            if (count > 0) {
                seenSums.add((double) total / count);
            }
        }
    }

    for (int j = 1; j <= n / 2; j++) {
        int target = sum * j / n;
        for (int k = 0; k < 1 << (n - j); k++) {
            int total = 0;
            for (int l = 0; l < n - j; l++) {
                if ((k & (1 << l)) != 0) {
                    total += nums[l + j];
                }
            }
            if (seenSums.contains((double) (sum - total) / (n - j))) {
                return true;
            }
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) return false;

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[] dp = new boolean[sum * n + 1];
    dp[0] = true;

    for (int num : nums) {
        for (int i = sum * n; i >= num; i--) {
            dp[i] = dp[i] || dp[i - num];
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0 && dp[sum * i]) {
            return true;
        }
    }

    return false;
}

