public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (n < Math.pow(2, k)) {
        return false;
    }
    Set<String> set = new HashSet<>();
    for (int i = 0; i <= n - k; i++) {
        set.add(s.substring(i, i + k));
    }
    return set.size() == Math.pow(2, k);
}

public boolean hasAllCodes(String s, int k) {
    if (s.length() < (1 << k)) {
        return false;
    }
    boolean[] seen = new boolean[1 << k];
    int uniqueCount = 0;
    int mask = (1 << k) - 1;
    int currentCode = 0;

    for (int i = 0; i < s.length(); i++) {
        if (i >= k) {
            currentCode = (currentCode & mask) << 1 | (s.charAt(i) - '0');
            if (!seen[currentCode]) {
                uniqueCount++;
                seen[currentCode] = true;
            }
        } else {
            currentCode = (currentCode << 1) | (s.charAt(i) - '0');
        }
    }

    return uniqueCount == (1 << k);
}

public boolean hasAllCodes(String s, int k) {
    if (s.length() < (1 << k)) {
        return false;
    }

    boolean[] seen = new boolean[1 << k];
    int uniqueCount = 0;
    int mask = (1 << k) - 1;
    int currentHash = 0;

    for (int i = 0; i < s.length(); i++) {
        currentHash = ((currentHash << 1) | (s.charAt(i) - '0')) & mask;
        if (i >= k - 1) {
            if (!seen[currentHash]) {
                seen[currentHash] = true;
                uniqueCount++;
            }
        }
    }

    return uniqueCount == (1 << k);
}

public boolean hasAllCodes(String s, int k) {
    if (s.length() < Math.pow(2, k)) {
        return false;
    }

    Set<String> substrings = new HashSet<>();

    for (int i = 0; i <= s.length() - k; i++) {
        substrings.add(s.substring(i, i + k));
    }

    return substrings.size() == Math.pow(2, k);
}

public boolean hasAllCodes(String s, int k) {
    // Check if the length of the string is sufficient to contain all possible binary substrings of length k
    if (s.length() < Math.pow(2, k)) {
        return false;
    }

    // Use a set to store unique substrings of length k
    HashSet<String> seen = new HashSet<>();

    // Iterate through the string and extract substrings of length k
    for (int i = 0; i <= s.length() - k; i++) {
        String substring = s.substring(i, i + k);
        seen.add(substring);
    }

    // Check if the number of unique substrings is equal to the total number of possible substrings of length k
    return seen.size() == Math.pow(2, k);
}

