public int minInsertions(String s) {
    int open = 0;
    int close = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            if (close % 2 == 1) {
                insertions++;
                close--;
            }
            open++;
        } else {
            close++;
        }

        if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
            if (close > 1) {
                insertions++;
            }
            i++;
        } else {
            insertions++;
        }
    }

    insertions += open * 2;
    insertions += close * 2;

    return insertions;
}

public int minInsertions(String s) {
        int open = 0; // To keep track of the number of unmatched '('
        int result = 0; // To count the number of insertions
        int i = 0; // Index to iterate through the string

        while (i < s.length()) {
            char c = s.charAt(i);

            if (c == '(') {
                open++;
                i++;
            } else {
                // Check if there is an unmatched '(' to pair with this ')'
                if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                    i += 2;
                } else {
                    result++;
                    i++;
                }

                // If we have an unmatched '(', append ')' to balance it
                if (open > 0) {
                    open--;
                    result++;
                }
            }
        }

        // Add the remaining unmatched '(' with a corresponding ')'
        result += open * 2;

        return result;
    }

public int minInsertions(String s) {
    int balance = 0;
    int insertions = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            balance++;
        } else {
            balance--;

            if (balance < 0) {
                insertions++;
                balance = 0;
            }
        }

        if (i + 1 < s.length() && s.charAt(i) == ')' && s.charAt(i + 1) == ')') {
            i++;
        } else if (i + 1 < s.length() && s.charAt(i) == '(' && s.charAt(i + 1) == '(') {
            i++;
        } else {
            insertions++;
        }
    }

    return insertions + balance * 2;
}

public int minInsertions(String s) {
    int left = 0, right = 0, ans = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (right % 2 == 1) {
                ans++;
                right--;
            }
            left++;
        } else {
            right++;
            if (right == 2 * left + 1) {
                right -= 2;
                left--;
                ans++;
            }
        }
    }

    return ans + (left - right / 2) * 2 + right % 2;
}

