}

public int minOperations(int n) {
    // Calculate the target value which is the middle element of the array
    int target = n;
    // Calculate the sum of the array elements
    long sum = 0;
    for (int i = 0; i < n; i++) {
        sum += (2 * i) + 1;
    }
    // Calculate the number of operations required
    return (int) Math.abs(sum - (1L * n * target)) / 2;
}

