public int maxAbsoluteSum(int[] nums) {
    int maxSum = 0;
    int minSum = 0;
    int currentMaxSum = 0;
    int currentMinSum = 0;

    for (int num : nums) {
        currentMaxSum = Math.max(currentMaxSum + num, 0);
        maxSum = Math.max(maxSum, currentMaxSum);

        currentMinSum = Math.min(currentMinSum + num, 0);
        minSum = Math.min(minSum, currentMinSum);
    }

    return Math.max(maxSum, Math.abs(minSum));
}

public int maxAbsoluteSum(int[] nums) {
    int maxSum = 0, minSum = 0, maxAbsolute = 0;

    for (int num : nums) {
        maxSum = Math.max(num, maxSum + num);
        minSum = Math.min(num, minSum + num);
        maxAbsolute = Math.max(maxAbsolute, Math.max(maxSum, Math.abs(minSum)));
    }

    return maxAbsolute;
}

public int maxAbsoluteSum(int[] nums) {
    int maxSum = 0;
    int minSum = 0;
    int currentSum = 0;

    for (int num : nums) {
        currentSum += num;
        maxSum = Math.max(maxSum, currentSum);
        minSum = Math.min(minSum, currentSum);
    }

    return Math.max(maxSum, -minSum);
}

public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }

    int maxSum = Integer.MIN_VALUE;
    int currentSum = 0;

    for (int num : nums) {
        currentSum = Math.max(num, currentSum + num);
        maxSum = Math.max(maxSum, currentSum);
    }

    int minSum = Integer.MAX_VALUE;
    currentSum = 0;

    for (int num : nums) {
        currentSum = Math.min(num, currentSum + num);
        minSum = Math.min(minSum, currentSum);
    }

    return Math.max(maxSum, Math.abs(minSum));
}

