    int result = 0;

    for (int num : nums) {
        maxSum = Math.max(num, maxSum + num);
        minSum = Math.min(num, minSum + num);
        result = Math.max(result, Math.max(maxSum, -minSum));
    }

    return result;
}

public static int findMinFibonacciNumbers(int k) {
        // Generate Fibonacci numbers up to k
        int[] fib = new int[20];
        fib[0] = 1;
        fib[1] = 1;
        for (int i = 2; i < fib.length; i++) {
            fib[i] = fib[i - 1] + fib[i - 2];
            if (fib[i] > k) {
                break;
            }
        }

        // Find the minimum number of Fibonacci numbers whose sum is equal to k
        int count = 0;
        for (int i = fib.length - 1; i >= 0; i--) {
            while (k >= fib[i]) {
                k -= fib[i];
                count++;
            }
            if (k == 0) {
                break;
            }
        }
        return count;
    }

public int findMinFibonacciNumbers(int k) {
        List<Integer> fibNumbers = new ArrayList<>();
        fibNumbers.add(1);
        fibNumbers.add(1);

        // Generate Fibonacci numbers up to k
        while (true) {
            int nextNumber = fibNumbers.get(fibNumbers.size() - 1) + fibNumbers.get(fibNumbers.size() - 2);
            if (nextNumber > k) {
                break;
            }
            fibNumbers.add(nextNumber);
        }

        int count = 0;
        int index = fibNumbers.size() - 1;

        while (k > 0 && index >= 0) {
            if (fibNumbers.get(index) <= k) {
                k -= fibNumbers.get(index);
                count++;
            }
            index--;
        }

        return count;
    }

public int findMinFibonacciNumbers(int k) {
    // Helper method to generate Fibonacci numbers up to k
    List<Integer> fibNumbers = new ArrayList<>();
    int a = 1, b = 1;
    fibNumbers.add(a);
    fibNumbers.add(b);
    while (b + a <= k) {
        int next = a + b;
        fibNumbers.add(next);
        a = b;
        b = next;
    }

    // Greedy algorithm to find the minimum number of Fibonacci numbers whose sum is k
    int count = 0;
    int i = fibNumbers.size() - 1;
    while (k > 0) {
        if (fibNumbers.get(i) <= k) {
            k -= fibNumbers.get(i);
            count++;
        }
        i--;
    }
    return count;
}

