        if (k <= 0) {
            throw new IllegalArgumentException("k must be a positive integer.");
        }

        int result = 0;
        List<Integer> Fibonacci = generateFibonacci(k);

        int index = Fibonacci.size() - 1;
        while (k > 0) {
            if (Fibonacci.get(index) <= k) {
