            count++;
            return;
        }
        for (int i = 0; i < n; i++) {
            if (!visited[i] && isPerfectSquare(previous + A[i])) {
                visited[i] = true;
                dfs(A, visited, i, A[i], depth + 1);
                visited[i] = false;
            }
        }
    }

    // Start DFS from each element
    for (int i = 0; i < n; i++) {
        visited[i] = true;
        dfs(A, visited, i, A[i], 1);
        visited[i] = false;
    }

    return count;
}

public static int largestRectangleArea(int[] heights) {
