public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Start from the second last digit and move backwards
    for (int i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            // Find the smallest digit on the right side of digits[i] but greater than digits[i]
            int minIndex = i + 1;
            for (int j = i + 2; j < len; j++) {
                if (digits[j] > digits[i] && digits[j] < digits[minIndex]) {
                    minIndex = j;
                }
            }

            // Swap the found digit with digits[i]
            char temp = digits[i];
            digits[i] = digits[minIndex];
            digits[minIndex] = temp;

            // Sort the digits after the ith position
            Arrays.sort(digits, i + 1, len);

            // Convert the character array back to an integer
            return Integer.parseInt(new String(digits));
        }
    }

    // If no rearrangement is possible
    return -1;
}

public static int findSmallestInteger(int n) {
        char[] digits = Integer.toString(n).toCharArray();
        int length = digits.length;

        // Start from the right, find the first digit that is smaller than the digit to its right
        int i;
        for (i = length - 2; i >= 0; i--) {
            if (digits[i] < digits[i + 1]) {
                break;
            }
        }

        // If no such digit is found, return -1 (no greater arrangement possible)
        if (i == -1) {
            return -1;
        }

        // Find the smallest digit on the right side of (i-th digit) that is greater than digits[i]
        int j;
        for (j = length - 1; j > i; j--) {
            if (digits[j] > digits[i]) {
                break;
            }
        }

        // Swap the found digits
        char temp = digits[i];
        digits[i] = digits[j];
        digits[j] = temp;

        // Sort the digits after the (i + 1)-th digit
        Arrays.sort(digits, i + 1, length);

        // Convert the digits back to an integer
        long result = Long.parseLong(String.valueOf(digits));

        // Check if the result is within the int range
        if (result <= Integer.MAX_VALUE) {
            return (int) result;
        } else {
            return -1;
        }
    }

